// This algorithm basically computes the maximum sum of any subarray.
// We initialize the variables maxSum and currSum as the first element in the array as they act as the base case.
// The algorithm iterates through the input array starting from the second element.
// Then it evaluates if the new element is greater than the sum of the current sum and the new element.
// If it is, it sets the current sum to the new element. If not, it adds the new element to the current sum.
// This algorithm works because it checks all subarrays by computing the sum of one element after the other.
// The maximum sum is returned at the end of the iteration.

function maxSubarraySum(arr) {
  // Check for null inputs.
  if (!arr) throw new Error("Input is invalid!");

  let maxSum = currSum = arr[0];
  // Check if array is all negatives.
  if (maxSum < 0) {
    for (let I = 1; I < arr.length; i++) {
      if (arr[i] > maxSum) maxSum = currSum = arr[i];
    }
  }
  for (let I = 1; I < arr.length; i++) {
    // Case when the current sum is less than the current element
    // i.e. We restart the current sum.
    if (currSum + arr[i] < arr[i]) currSum = arr[i];
    // Otherwise if the current sum and the current element is greater
    // than the current element, we add the current element to the current sum.
    else currSum += arr[i];
    // Update the maximum sum.
    maxSum = Math.max(currSum, maxSum);
  }
  return maxSum;
}

