```
#include <iostream>

using namespace std;

class circularQueue {
   private:
      int head, tail, size;
      int* queue;

   public:
      circularQueue(int k) {
         size = k;
         queue = new int[k];
         head = -1;
         tail = -1;
      }

      void enqueue(int data) {
         if ((tail + 1) % size == head) {
            cout << "Queue is full\n";
         } else if (head == -1) {
            head = 0;
            tail = 0;
            queue[tail] = data;
         } else {
            tail = (tail + 1) % size;
            queue[tail] = data;
         }
      }

      void dequeue() {
         if (head == -1) {
            cout << "Queue is empty\n";
         } else if (head == tail) {
            head = -1;
            tail = -1;
         } else {
            head = (head + 1) % size;
         }
      }

      int peek() {
         if (head == -1) {
            cout << "Queue is empty\n";
            return -1;
         } else {
            return queue[head];
         }
      }
};

int main() {
   circularQueue q(5);
   q.enqueue(1);
   q.enqueue(2);
   q.enqueue(3);
   q.enqueue(4);
   q.enqueue(5);
   q.enqueue(6);   // queue is full
   q.dequeue();
   q.dequeue();
   cout << q.peek() << "\n";  // 3
   q.dequeue();
   q.dequeue();
   q.dequeue();
   q.dequeue();   // queue is empty
   q.peek();   // queue is empty
   return 0;
}
```

In this implementation, we have kept track of the head and tail index of the queue, along with its size. During enqueue operation, if the tail index is equal to the size of the queue, we know that the queue is full. Otherwise, we add the new element to the next index of the tail and we increment the tail index to reflect that we have added a new element to the queue. 

During dequeue operation, we first check if the queue is empty. If the head index is equal to -1, we know that the queue is empty. If not, we check if there is only one element in the queue. If that is the case, we simply reset the head and tail index. Otherwise, we increment the head index to point to the next element in the queue. 

The peek operation allows us to return the element at the front of the queue, without actually removing it. If the queue is empty, we return a value of -1.

