```
import java.util.Scanner;

public class EuclideanAlgorithm {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Prompt user to enter two positive integers
        System.out.println("Enter two positive integers:");
        int num1 = getValidPositiveInteger(scanner);
        int num2 = getValidPositiveInteger(scanner);

        // Find the greatest common divisor using the Euclidean algorithm
        int gcd = findGCD(num1, num2);

        // Output the greatest common divisor
        System.out.printf("The greatest common divisor of %d and %d is %d", num1, num2, gcd);
    }

    /**
     * Prompt the user to enter a positive integer and validate that the input is valid
     * @param scanner the scanner to use for input
     * @return a valid positive integer entered by the user
     */
    public static int getValidPositiveInteger(Scanner scanner) {
        int num;
        do {
            System.out.print("Enter a positive integer: ");
            while (!scanner.hasNextInt()) { // Validate that input is a valid integer
                System.out.println("Invalid input. Please enter a valid positive integer.");
                scanner.next();
            }
            num = scanner.nextInt();
            if (num <= 0) { // Validate that input is a positive integer
                System.out.println("Invalid input. Please enter a valid positive integer.");
            }
        } while (num <= 0);
        return num;
    }

    /**
     * Find the greatest common divisor of two positive integers using the Euclidean algorithm
     * @param num1 the first positive integer
     * @param num2 the second positive integer
     * @return the greatest common divisor of num1 and num2
     */
    public static int findGCD(int num1, int num2) {
        while (num2 != 0) {
            int remainder = num1 % num2;
            num1 = num2;
            num2 = remainder;
        }
        return num1;
    }
}
```

